def L(a,z):return '「'+''.join(T[a-1:z])+'」'
B=[
dict(a=1,z=3,star=1,lit=L(1,3),
key=[('寄信','H5612','hasefer','書信、書卷'),('被擄','H1473','hagolah','被擄的人（群）'),('祭司','H3548','hakohanim','祭司'),('先知','H5030','hanavi','先知'),('沙番','H8227','shafan','（人名）'),('基瑪利','H1587','gemaryah','（人名）')],
gram=['**{H5612}**（sefer，書、信）：這個字可以指**書卷**，也可以指**一封信**。**耶利米書第一次出現一封「寄給被擄之人」的信。**這封信，是**由兩位使臣帶去的**，他們本來是**奉西底家的差遣去見尼布甲尼撒**。','**{H1473}**（golah，被擄的人）：這是**一個群體的名字**，不是一個人的名字。**耶利米寫信的對象，是一整群離開家園的人。**'],
exp=['二十九章是**書信**。前面二十七、二十八章，耶利米**面對面**對使臣、對王、對哈拿尼雅說話；現在，他**把話寫在紙上，寄給遠方的人**。這是**同一個先知，在兩個地方，向兩群人，說同一個信息：不要被短期的盼望騙了。**','時間是**耶哥尼雅（約雅斤）被擄之後**（主前597年）：王、太后、太監、首領、工匠、鐵匠都被帶走了。**留在耶路撒冷的人，以為被擄的人是被神丟棄的；被擄的人，以為自己很快就會回去。**耶利米的信，**對兩邊的想法，都要修正。**','請留意**送信的人**：以利亞薩是沙番的兒子，基瑪利是希勒家的兒子。**沙番、希勒家兩個家族，都是約西亞時代認真聽神話語的家**（王下二十二章）。**神把一封可能令人不舒服的信，交在可靠的人手上。**']),
dict(a=4,z=6,star=3,lit=L(4,6),
key=[('蓋造','H1129','bnu','建造'),('房屋','H1004','batim','房屋、家'),('栽種','H5193','vnatu','栽種'),('娶妻','H3947','qkhu','拿、娶'),('生兒女','H3205','vehoolidu','生養'),('生養眾多','H7235','vrabu','增多')],
gram=['**{H1129}**（bnu，要蓋造）、**{H5193}**（vnatu，要栽種）：這是**一連串的命令式**。**神對被擄的人說的第一句話，不是「準備回去」，而是「蓋房子、種田園」。**','**{H7235}**（vrabu，要增多）：這個字**回到創造的祝福**（創一28「生養眾多」）。**神在巴比倫，沒有收回創造時賜下的祝福。**'],
exp=['神的話，是**十個動作**：**蓋房子、住下去、栽種、吃果子、娶妻、生兒女、為兒子娶妻、使女兒嫁人、生養眾多、不致減少。**這是**一份完整的「長期居住」清單**：**居所、食物、婚姻、後代、人口。**','請留意**前後的對比**。哈拿尼雅說：**二年之內**，什麼都回復（二十八3）。耶利米信上說：**你們要蓋房子，住在其中。**這一章**是二十八章的另一半**：**真話不會把你留在半空中，而是讓你把腳放在地上。**','這也是**一個很深的屬靈提醒**：**被擄不是神的缺席。**神說「**是我使他們被擄**」（29:4）。**他們所在的地方，是神放他們去的地方；他們要活的日子，是神給他們的日子。**']),
dict(a=7,z=7,star=3,lit=L(7,7),
key=[('求平安','H1875','vedirshu','尋求、探求'),('那城','H5892','hair','城'),('禱告','H6419','vehitpalelu','祈禱'),('耶和華','H3068','yhwh','耶和華'),('被擄','H1540','higlethi','使被擄'),('得平安','H7965','shalom','平安、完整')],
gram=['**{H1875}**（darash，尋求）：這個字在**二十九章13節**也出現：「**你們尋求我**」（那裡用的是 baqash）。**同一個字根的「尋求」，先朝向那城的平安，再朝向神。**','**{H7965}**（shalom，平安）：在這一節裡出現**三次**：**求平安、得平安、也隨著得平安。**這個字的意思是**完整、安康、關係正常**，**不只是沒有戰爭。**'],
exp=['這一節是**全書最令人驚訝的一節**：**神要被擄的人，為擄他們的城禱告。**巴比倫**毀了耶路撒冷、燒了聖殿**，神卻說：**為那城求平安。**','這句話**有三層**：**一，求平安**：你要**盼望那城好**；**二，為那城禱告耶和華**：你要**把那城帶到神面前**；**三，那城得平安，你們也隨著得平安**：**你們的好處，與那城的好處連在一起。**','請留意：這**不是**叫人**忘記自己是誰**，也**不是**叫人**喜歡不義**。**同一本書後面，神會審判巴比倫（五十至五十一章）。**但是**在審判來到以前，神的百姓不是作旁觀者，而是作代求者。**']),
dict(a=8,z=9,star=2,lit=L(8,9),
key=[('先知','H5030','nviyekhem','先知'),('占卜','H7080','vqosmeykhem','占卜的人'),('夢','H2472','khalomotekhem','夢'),('誘惑','H5377','yashiu','欺騙、誘惑'),('假預言','H8267','sheqer','虛假'),('差遣','H7971','shlakhtim','差遣')],
gram=['**{H5377}**（nasha，欺騙）：這個字也是**夏娃說「蛇誘惑我」**（創三13）的那個字。**假先知的欺騙，是從伊甸園就有的老手法。**','**{H8267}**（sheqer，虛假、謊言）：這是**耶利米書最愛用的字之一**。**它指的不只是說錯話，而是「用神的名說神沒有說的話」。**'],
exp=['這兩節**是一個插入的警告**：**在叫人安心住下之前，先叫人提防「誘惑」。**為什麼？因為**被擄的人最想聽的就是：很快回去。****那些說「很快回去」的人，就會很受歡迎。**','請留意：**警告的對象，是「被擄的人自己」**：「**不要聽信自己所做的夢**」。**危險不只在外面的人，也在自己心裡那個想相信的聲音。**這一點，與二十八章**緊緊相連**。','這兩節**的重點是來源**：**「我並沒有差遣他們」**。**聽的人，不能只看他說得動不動聽，要問：他是從神那裡來的嗎？**']),
dict(a=10,z=10,star=3,lit=L(10,10),
key=[('七十','H7657','shivim','七十'),('滿了','H4390','melot','滿、成全'),('眷顧','H6485','efqod','眷顧、察看'),('恩言','H2896','hatov','美好的'),('成就','H6965','vahaqimoti','使站立、成就'),('仍回','H7725','lehashiv','使回來')],
gram=['**{H7657}**（shivim，七十）：與二十五章11--12節的「**七十年**」相同。**本講義不計算日子，不排時間表**，只問：**神給了他們一個時限，他們要怎樣在其中活？**','**{H6485}**（paqad，眷顧）：這個字有**兩面**：**審判的察看，也是恩典的眷顧。**同一個動詞，**對巴比倫是審判**（二十五12），**對被擄的人是眷顧**。'],
exp=['這一節**回答了一個問題**：**要住多久？**神說：**有時限。**這句話**不給日期，卻給盼望**：**這個地方不是永遠的家。**','請留意**這節的順序**：**住下來（5--7節），然後七十年滿了，神眷顧。**神沒有說「你們先準備回去」，而是**說「你們先好好住，我會在時候滿足時作我的事」**。**盼望是神作的，不是人準備出來的。**','**「我的恩言」**：直譯是**「我美好的話」**。**神要成就的，是祂自己已經說過的話。**這是**一個盼望的根基**：**不是人的猜測，也不是假先知的預言，而是神的話。**']),
dict(a=11,z=11,star=3,lit=L(11,11),
key=[('我知道','H3045','yadati','知道'),('意念','H4284','makhshavot','意念、計畫'),('平安','H7965','shalom','平安、完整'),('災禍','H7451','larah','災禍、惡'),('末後','H319','akharit','末後、結局'),('指望','H8615','tiqvah','指望、盼望')],
gram=['**{H319}**（akharit，末後）：這個字的意思是**「後面的部分」「結局」**。**「末後有指望」，是說：在故事的最後一頁，有指望。**不是說**每一天都順利**。','**{H8615}**（tiqvah，指望）：這個字的意思是**「一條繩子」**（約書亞記二18「紅線」就是這個字）。**指望是一條被抓住的繩，不是一種心情。**'],
exp=['這是**華人教會最常被單獨引用的一節**，也**是最容易被誤用的一節**。請你**回到原處境**：**這節是寫給在巴比倫的被擄之人；前面是七十年，後面是「你們要呼求我」。****它不是畢業賀卡，不是事業保證，而是神對一群受苦百姓的承諾。**','**「我知道」**：**神說「我知道我所計畫的」**。**在被擄的人眼中，一切都亂了；在神眼中，一切有計畫。****平安的意念**：**不是沒有痛苦的意念，而是完整的、有結局的意念。**','這一節**可以安慰人，也不應該被拿來騙人**。**它安慰人的地方：神對祂的百姓，沒有惡意。****它不能保證的地方：每一個人的每一個計畫都成功。**請與**5至7節一起讀**：**先住下來、先活下去，然後才是末後的指望。**']),
dict(a=12,z=14,star=3,lit=L(12,14),
key=[('呼求','H7121','vqratem','呼叫'),('禱告','H6419','vehitpalaltem','祈禱'),('應允','H8085','veshamati','聽見'),('尋求','H1245','uvqashtem','尋找'),('專心','H3824','levavkhem','心'),('招聚','H6908','vqibatsti','聚集')],
gram=['**{H3824}**（levav，心）：「**專心**」直譯是「**用你們全心**」。**這是申命記四29的語言**（「你若盡心盡性尋求他，就必尋見」）。**耶利米是在對被擄的人說：回到摩西的話。**','**{H1245}**（baqash，尋找）：**「尋求」**。**它在這裡的結果是「尋見」**；**神的回應是：「我必被你們尋見」**（14節）。**這是一個雙向的應許。**'],
exp=['這三節**是整段話的中心**：**呼求、禱告、尋求，神就應允、被尋見、招聚。**請留意**動詞的次序**：**人先動（呼求、禱告、尋求），神就動（應允、尋見、招聚）。**這不是一個機械的交換，而是**一種關係**。','**「若專心尋求我，就必尋見」**。**「若」字提醒我們：神要的不是一些儀式，而是一顆全心的人。****用心不是用腦。****用腦想盡辦法，用心尋求神。**','**「我必使你們被擄的人歸回，將你們從各國中招聚了來」**。**神的盼望，不是只把一個人帶回去，而是把一個民招聚回來。****回家的路，是從呼求開始的。**']),
dict(a=15,z=19,star=2,lit=L(15,19),
key=[('興起','H6965','heqim','使興起'),('無花果','H8384','katenim','像無花果'),('刀劍','H2719','kherev','刀劍'),('饑荒','H7458','raav','饑荒'),('瘟疫','H1698','dever','瘟疫'),('早起來','H7925','hashkem','早起')],
gram=['**{H8384}**（te’enah，無花果）：**這是二十四章「壞無花果」的呼應**。**留在耶路撒冷、自以為安全的人，是壞無花果；被擄去的人，是好無花果。**','**{H7925}**（shakham，早起）：這是**耶利米書的一個專用語**：**神「早起來差遣」先知**（七25、二十五4）。**神不是偶然說話，而是殷勤地、一再地說。**'],
exp=['在巴比倫的被擄之人**有人說：「耶和華在巴比倫為我們興起先知了。」**這一句話**很真實**：**人總是想找到一位說自己想聽的話的先知。**神對這句話**的回應，是轉向留在耶路撒冷的王和百姓。**','**留在耶路撒冷的人，以為自己是被保存下來的；神說，他們才是「極壞的無花果」。**這**與二十四章相接**：**好壞不是看人在哪裡，而是看人是否聽神的話。**','**19節給了原因**：**「因為他們沒有聽從我的話，就是我從早起來差遣我僕人眾先知去說的，無奈他們不聽」**。**審判的原因，不是神突然發怒，而是人一再不聽。**']),
dict(a=20,z=23,star=2,lit=L(20,23),
key=[('亞哈','H256','akhav','（人名）'),('西底家','H6667','tsidqiyahu','（人名）'),('賭咒','H7045','qlalah','咒詛'),('火','H784','baesh','火'),('醜事','H5039','nvalah','愚頑的事、醜事'),('見證','H5707','ve’ed','作見證的')],
gram=['**{H7045}**（qelalah，咒詛）：**這兩個假先知的名字，要變成一個咒詛的話語**：**願耶和華使你像西底家和亞哈一樣。**這是**人名變成了警告**。','**{H5039}**（nevalah，愚頑的事）：**聖經用這個字來形容「不顧神的約」的行為**。**假先知不只說錯話，還在生活上敗壞（與鄰舍的妻行淫）。**'],
exp=['這一段是**對兩位具體的人的宣告**：**亞哈（哥賴雅的兒子）和西底家（瑪西雅的兒子）**。**這個西底家，不是猶大王西底家，而是同名的另一個人。****他們用神的名說假預言，又在生活上敗壞。**','請留意：**他們死的方式，是「**在巴比倫王的手中**」，**被燒在火中**（22節）。**這是神對這兩人的具體宣告。**這**不是通則**，**不能用來論斷今日任何人**。','**最後一句很重要：「知道的是我，作見證的也是我。」**這句話**對受害的人是安慰**：**人看不見的，神都知道。****對說假話的人是警告：沒有一件事，是神不知道的。**']),
dict(a=24,z=28,star=2,lit=L(24,28),
key=[('示瑪雅','H8098','shmayahu','（人名）耶和華已聽見'),('西番雅','H6846','tsfanyah','（人名）'),('狂妄','H7696','meshugga','瘋狂'),('枷','H4115','hamahpekhet','枷'),('責備','H1605','gaarta','責備、斥責'),('長久','H752','arukah','長久')],
gram=['**{H8098}**（Shemayahu，示瑪雅）：這個名字的意思是「**耶和華已聽見**」。**名字很屬靈，內容卻是寫信給祭司，要求把耶利米關起來。**','**{H7696}**（meshugga，瘋狂）：這個字**在別處也被用來罵先知**（王下九11，罵一個年輕先知）。**示瑪雅叫耶利米「狂妄的人」，是用輕視的話貶低先知。**'],
exp=['**示瑪雅**是**一位在巴比倫的人**，**他寫信給耶路撒冷的祭司西番雅**，**要求把耶利米用「枷」和「鎖」關起來**。**他的理由是：耶利米寄信給被擄的人，說「被擄的事必長久」。**這是**一場來自被擄之地的攻擊**。','請留意：**示瑪雅所控告的，正是耶利米信中最真實的話：「你們要蓋造房屋，住在其中。」**（28節）**他把神的話，說成是危險的話。****有時候，真話會被說成是「消極」「不信」「沒有盼望」。**','**但請看西番雅的反應：他沒有照辦，而是把信「念給先知耶利米聽」**（29節）。**這位祭司，沒有被利用。****他選擇把事情攤開在被攻擊的人面前。**這是**一種誠實**。']),
dict(a=29,z=32,star=2,lit=L(29,32),
key=[('念','H7121','vayiqra','念、宣讀'),('倚靠','H982','vayavteakh','使倚靠'),('謊言','H8267','sheqer','虛假'),('刑罰','H6485','poqed','刑罰、察看'),('後裔','H2233','zaro','他的後裔'),('叛逆','H5627','sarah','叛逆')],
gram=['**{H982}**（batakh，倚靠）：**這個字是「信靠」的字**。**「使你們倚靠謊言」，是把人本來該信靠神的心，轉去信靠一句假話。****這是假預言最大的傷害。**','**{H5627}**（sarah，叛逆）：**這個字是「偏離」「背叛」的意思**，**也出現在二十八章16節。****向耶和華說叛逆的話，指的是否認神的話、對抗神的差遣。**'],
exp=['**神的回答，是叫耶利米再寄一封信給所有被擄的人**：**示瑪雅沒有被神差遣，他使人倚靠謊言。****神沒有叫耶利米為自己辯護，而是叫耶利米把真相交回給神的百姓。**','**審判的宣告，也是針對具體的一個人**：**示瑪雅和他的後裔，無一人存留，也看不見神要賜的福樂。****這是神對這一位的具體審判，**不是對任何今日講員的通則。**','**這一章的結尾，是「福樂」二字。****神說：「我百姓的福樂」（32節）。****即使在審判示瑪雅的時候，神的眼光仍然看著那將要賜給祂百姓的福樂。****審判是為了保護福樂。**']),
]
